      "activity_id": "U4-RESEARCH",
      "activity_name": "Research architecture differences",
      "activity_description": "Compare 1.x and 2.x deployment architectures for documentation.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "U4-DOCS",
      "activity_name": "Write reference documentation",
      "activity_description": "Create ref docs detailing 1.x vs 2.x deployment differences.",
      "most_likely_effort": 15
    },
    {
      "activity_id": "U4-REVIEW",
      "activity_name": "Review documentation",
      "activity_description": "Peer review and finalize architecture documentation.",
      "most_likely_effort": 5
